// Bench rack for 25 x 15 mL conical tubes (5 x 5 grid)
// Print orientation: base on XY plane, holes open upward (+Z)

// ---- Block dimensions ----
block_x = 118;      // block length (X), mm
block_y = 118;      // block width (Y), mm
block_z = 25;       // block height (Z), mm

// ---- Hole grid ----
cols = 5;           // holes along X
rows = 5;           // rows along Y
pitch = 22;         // centre-to-centre spacing, mm (both directions)

// ---- Holes ----
hole_d = 17.5;      // hole diameter, mm
hole_depth = 21;    // hole depth from top, mm
floor_t = block_z - hole_depth; // solid floor thickness (4 mm)

// ---- Misc ----
overcut = 0.5;      // extension of cutters past top face, mm
$fn = 96;           // circle resolution

difference() {
    // Solid block, centred in X/Y, resting on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_z]);

    // 5 x 5 grid of blind holes, grid centred on block
    for (i = [0 : cols - 1])
        for (j = [0 : rows - 1])
            translate([(i - (cols - 1)/2) * pitch,
                       (j - (rows - 1)/2) * pitch,
                       floor_t])
                cylinder(d = hole_d, h = hole_depth + overcut, $fn = 96);
}
